class ProviderClient:
    def __init__(self, http):
        self.http = http

    def _send(self, path):
        return self.http.get(path)

    def _ensure_success(self, response):
        response.raise_for_status()
        return response

    def _read_json(self, response):
        try:
            return response.json()
        except ValueError as error:
            raise ConnectionError("provider unavailable") from error

    def _read_id(self, payload):
        if not payload or "id" not in payload:
            raise ConnectionError("provider unavailable")
        return payload

    def get_account(self, account_id):
        response = self._ensure_success(self._send("/accounts/" + account_id))
        return self._read_id(self._read_json(response))

    def list_items(self, account_id):
        response = self.http.get("/accounts/" + account_id + "/items")
        response.raise_for_status()
        return response.json()

    def get_rate(self, currency):
        response = self.http.get("/rates/" + currency)
        response.raise_for_status()
        return response.json()

