namespace Sync.Providers;

using System.Net;

public sealed class ProviderClient(HttpClient http)
{
    private static readonly IReadOnlySet<HttpStatusCode> RetryStatusCodes =
        new HashSet<HttpStatusCode> { HttpStatusCode.TooManyRequests, HttpStatusCode.ServiceUnavailable };

    public async Task SyncAsync(CancellationToken ct) => Check(await http.PostAsync("/sync", null, ct));

    public async Task ImportAsync(CancellationToken ct) => Check(await http.PostAsync("/import", null, ct));

    public static bool ShouldRetry(HttpResponseMessage resp) => RetryStatusCodes.Contains(resp.StatusCode);

    private static void Check(HttpResponseMessage resp)
    {
        if (resp.StatusCode is HttpStatusCode.NotFound or HttpStatusCode.Gone)
            throw new InvalidOperationException("Provider record missing");
        if (resp.StatusCode is HttpStatusCode.Forbidden)
            throw new ProviderAuthException("Provider access denied");
        resp.EnsureSuccessStatusCode();
    }
}

