using System.Net;

public sealed class ProviderUnavailableException(string message, Exception inner) : Exception(message, inner)
{
    public static bool IsProviderFailure(Exception error, CancellationToken ct)
    {
        const int ServerErrorStatusEndExclusive = 600;
        if (ct.IsCancellationRequested) return false;
        return error switch
        {
            HttpRequestException http => http.StatusCode is null or HttpStatusCode.Unauthorized or HttpStatusCode.RequestTimeout
                || (int)http.StatusCode.Value is >= (int)HttpStatusCode.InternalServerError and < ServerErrorStatusEndExclusive,
            OperationCanceledException { InnerException: TimeoutException } => true,
            _ => false
        };
    }
}

